INSERT INTO skills (id, name, description, sort) VALUES ('S01', 'Problem framing', 'Problem statement 3 dòng + 5 clarifying question', 1);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S01', 'beginner', 'Xác định được câu hỏi chính và mục tiêu định lượng của đề.', 'Problem statement 3 dòng + 5 clarifying question');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S01', 'intermediate', 'Viết được problem statement dạng SCQ kèm tiêu chí thành công và phạm vi loại trừ.', 'Problem statement 3 dòng + 5 clarifying question');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S01', 'advanced', 'Phát hiện đề sai trọng tâm, tái định nghĩa vấn đề và bảo vệ được việc tái định nghĩa.', 'Problem statement 3 dòng + 5 clarifying question');
INSERT INTO skills (id, name, description, sort) VALUES ('S02', 'Hypothesis-driven thinking', 'Hypothesis board: giả thuyết → test → dữ liệu → kết luận', 2);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S02', 'beginner', 'Nêu được 2–3 giả thuyết cho nguyên nhân.', 'Hypothesis board: giả thuyết → test → dữ liệu → kết luận');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S02', 'intermediate', 'Xếp hạng giả thuyết theo impact × khả năng, chọn dữ liệu cần để bác bỏ.', 'Hypothesis board: giả thuyết → test → dữ liệu → kết luận');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S02', 'advanced', 'Dẫn dắt cả case bằng hypothesis tree, cập nhật giả thuyết khi có dữ liệu mới.', 'Hypothesis board: giả thuyết → test → dữ liệu → kết luận');
INSERT INTO skills (id, name, description, sort) VALUES ('S03', 'Issue tree / MECE', 'Issue tree có driver và nguồn dữ liệu ở mỗi lá', 3);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S03', 'beginner', 'Vẽ cây 2 tầng theo công thức (Revenue = P × Q).', 'Issue tree có driver và nguồn dữ liệu ở mỗi lá');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S03', 'intermediate', 'Chọn trục chia phù hợp ngữ cảnh; cây 3 tầng, MECE, driver đo được.', 'Issue tree có driver và nguồn dữ liệu ở mỗi lá');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S03', 'advanced', 'Thiết kế cây theo quyết định cần ra, cắt nhánh bằng 80/20 và giải thích lý do cắt.', 'Issue tree có driver và nguồn dữ liệu ở mỗi lá');
INSERT INTO skills (id, name, description, sort) VALUES ('S04', 'Business model understanding', 'Canvas 1 trang + 3 đòn bẩy lợi nhuận', 4);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S04', 'beginner', 'Mô tả được cách công ty kiếm tiền và ai trả tiền.', 'Canvas 1 trang + 3 đòn bẩy lợi nhuận');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S04', 'intermediate', 'Vẽ được value chain, cost structure và điểm khác biệt so với đối thủ.', 'Canvas 1 trang + 3 đòn bẩy lợi nhuận');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S04', 'advanced', 'Nhận diện đòn bẩy kinh tế của mô hình (asset-light, network effect, take rate) và giới hạn của nó.', 'Canvas 1 trang + 3 đòn bẩy lợi nhuận');
INSERT INTO skills (id, name, description, sort) VALUES ('S05', 'Market sizing', 'Bảng sizing: giả định, phép tính, sanity check, khoảng dao động', 5);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S05', 'beginner', 'Top-down 3 bước, giả định ghi rõ.', 'Bảng sizing: giả định, phép tính, sanity check, khoảng dao động');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S05', 'intermediate', 'Bottom-up, chọn được hướng phù hợp, sanity check bằng benchmark.', 'Bảng sizing: giả định, phép tính, sanity check, khoảng dao động');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S05', 'advanced', 'Sizing đa kịch bản, tách TAM/SAM/SOM, nêu độ nhạy theo giả định yếu nhất.', 'Bảng sizing: giả định, phép tính, sanity check, khoảng dao động');
INSERT INTO skills (id, name, description, sort) VALUES ('S06', 'Quantitative analysis', 'Bảng tính hiện công thức + 1 dòng kết luận mỗi bảng', 6);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S06', 'beginner', 'Tính % thay đổi, tỷ trọng, trung bình có trọng số không dùng máy tính.', 'Bảng tính hiện công thức + 1 dòng kết luận mỗi bảng');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S06', 'intermediate', 'Growth rate, CAGR, breakeven, contribution margin, phân rã chênh lệch.', 'Bảng tính hiện công thức + 1 dòng kết luận mỗi bảng');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S06', 'advanced', 'Sensitivity, scenario, phân rã variance nhiều biến, ước lượng nhanh có kiểm soát sai số.', 'Bảng tính hiện công thức + 1 dòng kết luận mỗi bảng');
INSERT INTO skills (id, name, description, sort) VALUES ('S07', 'Financial logic', 'Mô hình unit economics + bảng đánh giá đầu tư', 7);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S07', 'beginner', 'Đọc được P&L cơ bản, phân biệt fixed và variable cost.', 'Mô hình unit economics + bảng đánh giá đầu tư');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S07', 'intermediate', 'Unit economics, contribution margin, payback, vốn lưu động.', 'Mô hình unit economics + bảng đánh giá đầu tư');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S07', 'advanced', 'NPV/IRR ở mức ra quyết định, đánh giá chất lượng lợi nhuận và rủi ro dòng tiền.', 'Mô hình unit economics + bảng đánh giá đầu tư');
INSERT INTO skills (id, name, description, sort) VALUES ('S08', 'Customer & marketing analysis', 'Bảng segment × funnel + CAC/LTV theo kênh', 8);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S08', 'beginner', 'Phân biệt segment, nêu được nhu cầu chính của một nhóm.', 'Bảng segment × funnel + CAC/LTV theo kênh');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S08', 'intermediate', 'Segmentation có tiêu chí, phân tích funnel, định vị và value proposition.', 'Bảng segment × funnel + CAC/LTV theo kênh');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S08', 'advanced', 'CAC–LTV theo kênh, trade-off ngân sách marketing, đọc cohort và retention.', 'Bảng segment × funnel + CAC/LTV theo kênh');
INSERT INTO skills (id, name, description, sort) VALUES ('S09', 'Operations & supply chain logic', 'Process map có số + bảng trade-off cost vs service', 9);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S09', 'beginner', 'Vẽ được flow từ nhà cung cấp đến khách hàng, nhận diện bottleneck.', 'Process map có số + bảng trade-off cost vs service');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S09', 'intermediate', 'Tính capacity, utilization, lead time, tồn kho an toàn, chi phí phục vụ.', 'Process map có số + bảng trade-off cost vs service');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S09', 'advanced', 'Thiết kế lại network hoặc chính sách tồn kho với trade-off cost–service–risk định lượng.', 'Process map có số + bảng trade-off cost vs service');
INSERT INTO skills (id, name, description, sort) VALUES ('S10', 'Competitive strategy', 'Positioning map + kịch bản phản ứng đối thủ', 10);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S10', 'beginner', 'So sánh ta với 2 đối thủ trên 3 tiêu chí.', 'Positioning map + kịch bản phản ứng đối thủ');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S10', 'intermediate', 'Phân tích cấu trúc ngành, lợi thế cạnh tranh, phản ứng của đối thủ.', 'Positioning map + kịch bản phản ứng đối thủ');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S10', 'advanced', 'Đề xuất nước đi có tính đến phản ứng đối thủ và độ bền của lợi thế.', 'Positioning map + kịch bản phản ứng đối thủ');
INSERT INTO skills (id, name, description, sort) VALUES ('S11', 'Data / chart interpretation', 'Chart có action title + 3 gạch “so what”', 11);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S11', 'beginner', 'Đọc đúng trục, đơn vị và xu hướng của một chart.', 'Chart có action title + 3 gạch “so what”');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S11', 'intermediate', 'So sánh nhiều chart, phát hiện mâu thuẫn, tách mix effect khỏi rate effect.', 'Chart có action title + 3 gạch “so what”');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S11', 'advanced', 'Chọn chart đúng cho luận điểm, phát hiện chart gây hiểu nhầm, tự thiết kế exhibit.', 'Chart có action title + 3 gạch “so what”');
INSERT INTO skills (id, name, description, sort) VALUES ('S12', 'Insight synthesis', 'Pyramid 1 trang: governing thought + 3 nhánh + bằng chứng', 12);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S12', 'beginner', 'Tóm tắt phát hiện chính thành một câu.', 'Pyramid 1 trang: governing thought + 3 nhánh + bằng chứng');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S12', 'intermediate', 'Gộp nhiều phân tích thành 3 thông điệp không chồng lấn, có bằng chứng số.', 'Pyramid 1 trang: governing thought + 3 nhánh + bằng chứng');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S12', 'advanced', 'Xây governing thought và nhóm lập luận theo pyramid principle.', 'Pyramid 1 trang: governing thought + 3 nhánh + bằng chứng');
INSERT INTO skills (id, name, description, sort) VALUES ('S13', 'Recommendation design', 'Recommendation table: option, tiêu chí, impact, rủi ro, mitigation', 13);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S13', 'beginner', 'Đưa được một đề xuất rõ ràng, không mơ hồ.', 'Recommendation table: option, tiêu chí, impact, rủi ro, mitigation');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S13', 'intermediate', 'Đề xuất có đối tượng, hành động, thời gian, chi phí, impact ước lượng.', 'Recommendation table: option, tiêu chí, impact, rủi ro, mitigation');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S13', 'advanced', 'So sánh phương án theo tiêu chí, nêu rủi ro và cách giảm thiểu, có roadmap và điều kiện dừng.', 'Recommendation table: option, tiêu chí, impact, rủi ro, mitigation');
INSERT INTO skills (id, name, description, sort) VALUES ('S14', 'Slide storyline', 'Ghost deck + deck hoàn chỉnh có action title', 14);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S14', 'beginner', 'Viết được action title cho một slide.', 'Ghost deck + deck hoàn chỉnh có action title');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S14', 'intermediate', 'Sắp xếp storyline 10–12 slide theo mạch SCR, mỗi slide một thông điệp.', 'Ghost deck + deck hoàn chỉnh có action title');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S14', 'advanced', 'Thiết kế deck theo đối tượng nghe, có appendix phòng thủ và ghost deck dựng trước khi phân tích.', 'Ghost deck + deck hoàn chỉnh có action title');
INSERT INTO skills (id, name, description, sort) VALUES ('S15', 'Pitching & Q&A', 'Bản ghi pitch + Q&A log chấm theo rubric', 15);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S15', 'beginner', 'Trình bày 90 giây rõ ràng, không đọc slide.', 'Bản ghi pitch + Q&A log chấm theo rubric');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S15', 'intermediate', 'Pitch 7 phút theo mạch, phân vai trong team, trả lời câu hỏi trực diện.', 'Bản ghi pitch + Q&A log chấm theo rubric');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S15', 'advanced', 'Xử lý câu hỏi phản biện, thừa nhận giới hạn mà không mất thế, điều hướng về luận điểm chính.', 'Bản ghi pitch + Q&A log chấm theo rubric');
INSERT INTO skills (id, name, description, sort) VALUES ('S16', 'Business judgment', 'Risk & feasibility memo + “what would change my mind”', 16);
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S16', 'beginner', 'Nhận ra đề xuất nào bất khả thi về nguồn lực.', 'Risk & feasibility memo + “what would change my mind”');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S16', 'intermediate', 'Cân nhắc trade-off ngắn hạn – dài hạn, khả thi vận hành, phản ứng các bên.', 'Risk & feasibility memo + “what would change my mind”');
INSERT INTO skill_levels (skill_id, level, descriptor, evidence) VALUES ('S16', 'advanced', 'Ra khuyến nghị khi dữ liệu thiếu, nêu rõ điều gì sẽ làm mình đổi ý.', 'Risk & feasibility memo + “what would change my mind”');
INSERT INTO tracks (id, name, role, sort) VALUES ('A', 'Business Case Foundations', 'Biến đề bài thành câu hỏi trả lời được; hiểu doanh nghiệp kiếm tiền thế nào.', 1);
INSERT INTO tracks (id, name, role, sort) VALUES ('B', 'Quantitative Case Skills', 'Làm chủ số: math dưới áp lực, sizing, đọc chart, phân rã chênh lệch.', 2);
INSERT INTO tracks (id, name, role, sort) VALUES ('C', 'Strategy & Consulting Cases', 'Các dạng case chuẩn: profitability, market entry, growth, pricing, M&A.', 3);
INSERT INTO tracks (id, name, role, sort) VALUES ('D', 'Case Competition Mastery', 'Quy trình 24–72 giờ theo team: chia việc, hợp nhất, deck, pitch, Q&A.', 4);
INSERT INTO tracks (id, name, role, sort) VALUES ('E', 'Marketing Cases', 'Consumer, segmentation, funnel, pricing, go-to-market, growth.', 5);
INSERT INTO tracks (id, name, role, sort) VALUES ('F', 'Supply Chain & Operations', 'Process, capacity, tồn kho, network, cost-to-serve, S&OP.', 6);
INSERT INTO tracks (id, name, role, sort) VALUES ('G', 'Finance for Business Cases', 'Đọc báo cáo, unit economics, đánh giá đầu tư ở mức đủ dùng cho case.', 7);
INSERT INTO tracks (id, name, role, sort) VALUES ('H', 'Industry Case Library', 'Kiến thức ngành đủ để đặt câu hỏi đúng: retail, F&B, FMCG, banking, healthcare, logistics, tech, năng lượng.', 8);
INSERT INTO tracks (id, name, role, sort) VALUES ('I', 'Presentation & Storytelling', 'Pyramid, action title, exhibit design, storyboard, deck, thuyết trình.', 9);
INSERT INTO tracks (id, name, role, sort) VALUES ('J', 'Interview Simulation', 'Live case, candidate-led, math dưới áp lực, fit, mock panel.', 10);
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('A1', 'A', 'Đọc đề và định khung vấn đề', 1, 1, 'Sau module này người học biến một đề case dài 1 trang thành một problem statement 3 dòng có câu hỏi chính, tiêu chí thành công định lượng, và phạm vi loại trừ.', '[]', 140, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A1', 'S01', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A1', 'S16', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('A2', 'A', 'Issue tree và tư duy MECE', 1, 1, 'Người học chia một vấn đề thành cây 3 tầng MECE, mỗi lá gắn với một driver đo được và một nguồn dữ liệu.', '[]', 130, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A2', 'S03', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A2', 'S02', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('A3', 'A', 'Hiểu mô hình kinh doanh', 1, 1, 'Người học giải thích được một doanh nghiệp kiếm tiền thế nào, mất tiền ở đâu, và ba đòn bẩy lợi nhuận lớn nhất của nó.', '[]', 135, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A3', 'S04', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A3', 'S07', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('A4', 'A', 'Từ phân tích đến khuyến nghị đầu tiên', 1, 1, 'Người học kết thúc một mini case bằng một khuyến nghị cụ thể: làm gì, ai làm, tốn bao nhiêu, được gì, rủi ro gì.', '[]', 95, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A4', 'S12', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('A4', 'S13', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('B1', 'B', 'Case math nền', 1, 2, 'Người học tính nhẩm chính xác dưới áp lực: phần trăm, tỷ lệ, trung bình có trọng số, breakeven — nói ra được từng bước khi đang tính.', '[]', 87, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B1', 'S06', 'primary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('B2', 'B', 'Market sizing', 1, 2, 'Người học ước lượng quy mô một thị trường lạ trong 8 phút bằng cả top-down lẫn bottom-up, ghi rõ giả định và kiểm tra tính hợp lý.', '[]', 118, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B2', 'S05', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B2', 'S16', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('B3', 'B', 'Đọc chart và exhibit', 1, 2, 'Người học rút ra 3 “so what” từ một exhibit trong 4 phút, và phát hiện được chart trình bày gây hiểu nhầm.', '[]', 110, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B3', 'S11', 'primary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('B4', 'B', 'Phân rã chênh lệch, scenario và sensitivity', 1, 2, 'Người học giải thích được một khoản chênh lệch bằng các cấu phần định lượng và chỉ ra giả định nào chi phối kết quả.', '[]', 85, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B4', 'S06', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('B4', 'S16', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('C1', 'C', 'Profitability & cost case', 2, 3, 'Người học tìm ra nguyên nhân thật sự của một khoản lợi nhuận sụt giảm bằng cách đi từ tổng xuống đến phân khúc, sản phẩm hoặc điểm bán cụ thể.', '[]', 245, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C1', 'S03', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C1', 'S06', 'secondary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C1', 'S07', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('C2', 'C', 'Market entry & growth strategy', 2, 3, 'Người học ra được quyết định vào hay không vào một thị trường, dựa trên sizing, cấu trúc cạnh tranh, năng lực nội tại và phương thức thâm nhập.', '[]', 240, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C2', 'S05', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C2', 'S10', 'secondary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C2', 'S16', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('C3', 'C', 'Pricing, product & portfolio', 2, 3, 'Người học định giá một sản phẩm bằng ba cách tiếp cận và chọn được cách phù hợp, đồng thời đánh giá được nên giữ hay bỏ một dòng sản phẩm.', '[]', 225, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C3', 'S07', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C3', 'S08', 'secondary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C3', 'S10', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('C4', 'C', 'M&A, đầu tư và turnaround', 2, 3, 'Người học đánh giá một thương vụ hoặc một khoản đầu tư lớn: lý do chiến lược, con số, synergy, rủi ro tích hợp, và điều kiện để nói không.', '[]', 415, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C4', 'S07', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C4', 'S16', 'secondary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('C4', 'S13', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('D1', 'D', 'Quy trình 24–72 giờ', 3, 4, 'Người học điều hành được một team 4 người qua một vòng thi có hạn: chia việc theo issue tree, đặt mốc, và luôn có một bản nộp được ở mọi thời điểm.', '[]', 1500, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D1', 'S01', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D1', 'S16', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('D2', 'D', 'Hợp nhất phân tích thành một storyline', 3, 4, 'Người học gộp phân tích của 4 người thành một mạch lập luận duy nhất, loại bỏ phần thừa, và viết được governing thought cho cả bài.', '[]', 140, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D2', 'S12', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D2', 'S14', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('D3', 'D', 'Deck thi và exhibit thuyết phục', 3, 4, 'Người học dựng một deck 12–15 slide thi đấu được: mỗi slide một thông điệp, exhibit tự giải thích, appendix đủ để phòng thủ.', '[]', 120, 'published', 1, 0);
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D3', 'S14', 'primary');
INSERT INTO module_skills (module_id, skill_id, role) VALUES ('D3', 'S11', 'secondary');
INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('D4', 'D', 'Pitch và Q&A trước ban giám khảo', 3, 4, 'Người học trình bày 7 phút theo team và chịu được 10 phút phản biện, giữ được luận điểm chính khi bị chất vấn.', '[]', 50, 'published', 1, 0);
