INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('E1', 'E', 'Khách hàng, phân khúc và định vị', 2, 3, 'Người học chia thị trường thành các phân khúc có thể hành động được và viết được value proposition cho phân khúc mục tiêu.', '[]', 185, 'published', 1, 0);
