INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('E3', 'E', 'Brand, go-to-market và marketing plan', 2, 3, 'Người học viết được một marketing plan nối liền với P&L: mục tiêu, phân khúc, thông điệp, kênh, ngân sách, chỉ số theo dõi.', '[]', 415, 'published', 1, 0);
