INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('F1', 'F', 'Process, capacity và bottleneck', 2, 3, 'Người học vẽ được process map có số và tìm ra nút thắt thật, rồi tính được sản lượng tăng thêm nếu gỡ nút đó.', '[]', 155, 'published', 1, 0);
