INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('F2', 'F', 'Tồn kho và thiết kế mạng lưới', 2, 3, 'Người học đặt được chính sách tồn kho và bố trí kho vận với trade-off giữa chi phí và mức dịch vụ được định lượng.', '[]', 190, 'published', 1, 0);
