INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('F3', 'F', 'Cost-to-serve, sourcing và S&OP', 2, 3, 'Người học tính được chi phí phục vụ từng khách hàng hoặc kênh và chỉ ra khách nào đang làm mất tiền của công ty.', '[]', 110, 'published', 1, 0);
