INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('G1', 'G', 'Đọc báo cáo tài chính cho người làm case', 2, 3, 'Người học đọc một bộ báo cáo tài chính trong 15 phút và nêu được ba điều đáng lo nhất về sức khoẻ doanh nghiệp.', '[]', 110, 'published', 1, 0);
