INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('G2', 'G', 'Unit economics', 2, 3, 'Người học dựng được mô hình kinh tế trên một đơn vị (một khách, một đơn hàng, một cửa hàng) và biết đơn vị đó có lãi ở mức nào.', '[]', 160, 'published', 1, 0);
