INSERT INTO modules (id, track_id, title, level_min, level_max, outcome, out_of_scope, est_minutes, status, version, published_at) VALUES ('H1', 'H', 'Tiêu dùng: retail, F&B, FMCG', 3, 3, 'Người học đặt được đúng câu hỏi đầu tiên khi gặp một case ngành tiêu dùng, nhờ nắm các chỉ số và động lực kinh tế đặc thù của ngành.', '[]', 115, 'published', 1, 0);
