INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.1', 1, 'Không có chuỗi logic; nhảy thẳng đến một con số.');
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.1', 2, 'Có chuỗi nhưng các dòng không nhân được với nhau về đơn vị, hoặc chọn hướng không phù hợp với đề.');
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.1', 3, 'Chuỗi khép kín, đơn vị khớp, hướng tiếp cận hợp lý và nói được lý do chọn.');
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.1', 4, 'Chuỗi khép kín và có bộ lọc thu hẹp về đúng nhóm khách thật; giải thích được vì sao bỏ nhóm nào.');
INSERT INTO rubric_criteria (id, rubric_id, name, weight, skill_id, sort) VALUES ('RM-B2.2', 'RM-B2', 'Giả định ghi rõ và có cơ sở', 25, 'S05', 2);
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.2', 1, 'Con số xuất hiện mà không nói ở đâu ra.');
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.2', 2, 'Có nêu giả định nhưng không có cơ sở, hoặc nêu sau khi đã ra kết quả.');
