INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.3', 2, 'Đúng phép tính nhưng bỏ sót một nhân tử bắt buộc (tần suất, tỷ lệ lấp đầy, số kỳ).');
