INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.4', 3, 'Thực hiện ít nhất một phép kiểm tra cụ thể và nói kết quả kiểm tra.');
INSERT INTO rubric_criterion_levels (criterion_id, level, descriptor) VALUES ('RM-B2.4', 4, 'Kiểm tra bằng hai góc độc lập (chi tiêu đầu người và đối chiếu thị trường quen), và điều chỉnh nếu thấy lệch.');
