INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-004', '004', 'Chuỗi nhà sách muốn mở thêm 20 cửa hàng', 'Bán lẻ', 'Một chuỗi nhà sách có 12 cửa hàng tại Hà Nội và TP.HCM, doanh thu đi ngang ba năm liền. Ban giám đốc vừa chốt kế hoạch mở thêm 20 cửa hàng trong hai năm và muốn bạn “giúp triển khai cho nhanh”.', 'Trước khi bàn cách triển khai, vấn đề thật sự cần giải ở đây là gì? Viết problem statement và năm câu hỏi làm rõ.', 25, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-004.r1', 'C-004', 'Nếu hỏi doanh thu', 'đi ngang quanh mức 180 tỷ đồng/năm', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-004.r2', 'C-004', 'Nếu hỏi lợi nhuận', '4 cửa hàng đang lỗ', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-004.r3', 'C-004', 'Nếu hỏi vì sao mở rộng', '“để tăng doanh thu”', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-004.r4', 'C-004', 'Nếu hỏi ngân sách', 'chưa có con số.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-004.t1', 'C-004', 'Đề mời người học nhảy thẳng vào “mở ở đâu, mở thế nào”. Nhưng khi 4 trong 12 cửa hàng đang lỗ, nhân rộng một mô hình chưa lành là cách nhanh nhất để lỗ to hơn. Nhắm mã FRM-04 và FRM-01.', 'FRM-04');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-004', 'Problem statement phải tái định nghĩa: câu hỏi đúng là “mô hình cửa hàng hiện tại có đủ lành để nhân rộng không, và điều kiện nào phải đạt trước khi mở thêm”. Năm câu hỏi làm rõ phải có ít nhất một câu về kinh tế một cửa hàng và một câu về lý do 4 cửa hàng lỗ.', '{}', 'Có tái định nghĩa vấn đề: mức 3 trở lên · Chỉ nhắc lại kế hoạch mở rộng: trần mức 2 · Hỏi được về kinh tế một cửa hàng: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-008', '008', 'Doanh thu ứng dụng gọi xe giảm 12% một quý', 'Công nghệ', 'Một ứng dụng gọi xe hai bánh hoạt động ở bốn thành phố. Quý vừa rồi tổng giá trị giao dịch giảm 12% so với quý trước, trong khi số người dùng mở ứng dụng không đổi.', 'Vẽ cây phân tích để tìm nguyên nhân, và nói bạn sẽ đào nhánh nào trước cùng lý do.', 30, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-008.r1', 'C-008', 'Phát sẵn', 'Exhibit 1 — doanh thu theo tuần trong 26 tuần, có một bậc gãy ở tuần 14', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-008.r2', 'C-008', 'Nếu hỏi số chuyến', 'giảm 15%', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-008.r3', 'C-008', 'Nếu hỏi giá trung bình mỗi chuyến', 'tăng 4%', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-008.r4', 'C-008', 'Nếu hỏi số tài xế hoạt động', 'giảm 18%', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-008.r5', 'C-008', 'Nếu hỏi khuyến mãi', 'ngân sách khuyến mãi bị cắt từ tuần 13.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-008.t1', 'C-008', 'Số người mở ứng dụng không đổi khiến người học tập trung vào phía cầu. Nguyên nhân nằm ở phía cung: tài xế rời đi sau khi cắt thưởng, thời gian chờ tăng, chuyến bị huỷ. Nhắm TRE-05 chia theo framework thay vì theo vấn đề.', 'TRE-05');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-008', 'Cây phải tách GMV = số chuyến × giá trị mỗi chuyến, rồi số chuyến = nhu cầu đặt × tỷ lệ ghép thành công. Nhánh đáng đào trước là tỷ lệ ghép, vì dữ liệu cho thấy cầu giữ nguyên mà cung giảm. Bậc gãy ở tuần 14 khớp với mốc cắt thưởng tuần 13.', '{}', 'Tách được tỷ lệ ghép ra khỏi nhu cầu: mức 4 · Chỉ chia theo 4P hoặc theo phòng ban: trần mức 2 · Nối được bậc gãy tuần 14 với mốc chính sách: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-011', '011', 'Quán cà phê tự vận hành và quán nhượng quyền', 'F&B', 'Hai quán cà phê cùng quy mô, cùng vị trí tương đương ở quận trung tâm. Một quán do chủ tự vận hành, một quán nhượng quyền từ một thương hiệu chuỗi.', 'Hai mô hình khác nhau ở đâu về mặt kinh tế, và mô hình nào rủi ro hơn cho người bỏ vốn?', 35, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-011.r1', 'C-011', 'Phát sẵn', 'Hai bảng P&L rút gọn 12 tháng, cùng doanh thu ~2,4 tỷ đồng/năm', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-011.r2', 'C-011', 'Phát sẵn', 'Quán nhượng quyền có phí nhượng quyền 5% doanh thu và phí marketing 2%', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-011.r3', 'C-011', 'Phát sẵn', 'Quán tự vận hành có chi phí nguyên liệu cao hơn 4 điểm phần trăm và chi phí marketing thấp hơn.', 3);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-011.t1', 'C-011', 'Người học dễ so sánh lợi nhuận cuối cùng rồi kết luận. Điểm thật là cấu trúc: nhượng quyền biến một phần chi phí cố định thành biến đổi, nên lỗ ít hơn khi doanh thu thấp nhưng lãi ít hơn khi doanh thu cao. Nhắm BIZ-01 và BIZ-03.', 'BIZ-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-011', 'Canvas cho mỗi mô hình · Ba đòn bẩy lợi nhuận: giá bán trung bình, chi phí nguyên liệu trên ly, số ly mỗi ngày · Kết luận phải nói về độ nhạy với doanh thu, không chỉ về mức lợi nhuận. Điểm hoà vốn của quán nhượng quyền thấp hơn nhưng trần lợi nhuận cũng thấp hơn.', '{}', 'Nói được về cấu trúc cố định / biến đổi: mức 4 · Chỉ so lợi nhuận tuyệt đối: trần mức 2 · Tính được điểm hoà vốn của cả hai: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-014', '014', 'Cửa hàng tiện lợi lỗ ở 6 trong 20 điểm bán', 'Bán lẻ', 'Một chuỗi cửa hàng tiện lợi 20 điểm bán tại một thành phố lớn. Tổng thể vẫn có lãi mỏng, nhưng 6 điểm bán lỗ và ban giám đốc đang cân nhắc đóng cả 6.', 'Có nên đóng 6 điểm bán này không? Nếu không đóng hết thì đóng cái nào.', 45, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-014.r1', 'C-014', 'Phát sẵn', 'Exhibit 1 — bảng 20 điểm bán: doanh thu, biên gộp, tiền thuê, lương, lợi nhuận', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-014.r2', 'C-014', 'Phát sẵn', 'Exhibit 2 — doanh thu theo giờ của 3 điểm bán đại diện', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-014.r3', 'C-014', 'Nếu hỏi hợp đồng thuê', 'còn 1–4 năm tuỳ điểm', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-014.r4', 'C-014', 'Nếu hỏi chi phí chung phân bổ', '60 triệu đồng/tháng chia đều cho 20 điểm.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-014.t1', 'C-014', 'Chi phí chung được phân bổ đều. Ba trong sáu điểm bán có biên đóng góp dương và chỉ lỗ sau khi gánh chi phí chung — đóng chúng sẽ làm tổng lợi nhuận chuỗi giảm. Nhắm FIN-05 và SCM-06.', 'FIN-05');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-014', 'Tách biên đóng góp khỏi lợi nhuận sau phân bổ · Phân 6 điểm thành ba nhóm: đóng ngay (biên đóng góp âm, hợp đồng sắp hết), cứu (biên dương, có vấn đề vận hành cụ thể), giữ nguyên · Khuyến nghị đóng 2, cứu 3, theo dõi 1, kèm ước lượng tác động lợi nhuận.', '{}', 'Nhận ra bẫy phân bổ chi phí chung: mức 4 ở tiêu chí định lượng · Đề xuất đóng cả 6: trần mức 2 toàn bài · Có ước lượng tác động của khuyến nghị: +1 mức ở tiêu chí khuyến nghị.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-021', '021', 'Ngân hàng 24 đề sizing lạ', 'Tài chính', 'Không phải một đề mà là một ngân hàng đề, chia ba nhóm cơ cấu để mỗi lượt rút ra một bộ cân bằng.', 'Nhóm cầu (8 đề): nước giặt, kính mắt, sách giáo khoa cũ, dịch vụ trông trẻ theo giờ, thức ăn thú cưng, bảo hiểm xe máy, vé xe khách liên tỉnh, đồ chơi trẻ em. Nhóm cung (8 đề): tiệm giặt sấy, sân pickleball, phòng khám nha khoa, tiệm sửa xe máy, quán karaoke, nhà thuốc, cửa hàng điện thoại, studio chụp ảnh. Nhóm B2B (8 đề): phần mềm kế toán cho SME, dịch vụ vệ sinh văn phòng, in ấn bao bì, tuyển dụng nhân sự cấp trung, thuê máy photocopy, kiểm định thang máy, đồng phục doanh nghiệp, phần mềm chấm công.', 8, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-021.r1', 'C-021', 'Phát sẵn', 'Không phát gì. Người điều phối chỉ trả lời “bạn tự ước lượng” cho mọi câu hỏi về số liệu, trừ giá bán khi người học đã nêu một khoảng và chỉ xin xác nhận.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-021.t1', 'C-021', 'Nhóm B2B là bẫy hệ thống: người học quen mở bài bằng dân số sẽ tắc. Nhắm SIZ-07. Ít nhất hai đề trong mỗi bộ rút ra phải thuộc nhóm không quen.', 'SIZ-07');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-021', 'Mỗi đề có một file khung gồm: hướng khuyến nghị, chuỗi tính mẫu, khoảng kết quả chấp nhận được theo bậc độ lớn, và giả định chi phối. Xem mẫu đầy đủ ở đặc tả module B2.', '{}', 'Kết quả trong khoảng chấp nhận về bậc độ lớn: đạt tiêu chí tính toán · Không sanity check: trần mức 2 ở tiêu chí đó bất kể kết quả đúng.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-026', '026', 'Biên lợi nhuận gộp giảm 3 điểm dù giá bán tăng', 'Sản xuất', 'Một doanh nghiệp sản xuất đồ gia dụng bán qua ba kênh: hiện đại, truyền thống và trực tuyến. Năm nay giá bán trung bình tăng 6% nhưng biên lợi nhuận gộp giảm từ 34% xuống 31%.', 'Giải thích chênh lệch 3 điểm này bằng các cấu phần định lượng, rồi cho biết cấu phần nào cần can thiệp trước.', 60, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-026.r1', 'C-026', 'Phát sẵn', 'Dataset: doanh thu, sản lượng, giá, giá vốn theo 3 kênh × 4 dòng sản phẩm × 2 năm', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-026.r2', 'C-026', 'Phát sẵn', 'Exhibit 1 — cơ cấu doanh thu theo kênh hai năm', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-026.r3', 'C-026', 'Phát sẵn', 'Exhibit 2 — giá vốn đơn vị theo dòng sản phẩm', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-026.r4', 'C-026', 'Phát sẵn', 'Exhibit 3 — chiết khấu thương mại theo kênh.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-026.t1', 'C-026', 'Giá tăng thật, nhưng tỷ trọng kênh truyền thống (chiết khấu cao, biên thấp) tăng từ 28% lên 41%. Đây là mix effect thuần. Người học nhìn giá vốn sẽ không tìm ra. Nhắm VAR-02 trộn mix và rate.', 'VAR-02');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-026', 'Bridge từ 34% xuống 31% với bốn cấu phần: hiệu ứng giá +1,8 điểm · hiệu ứng giá vốn −1,5 điểm · hiệu ứng mix kênh −2,9 điểm · hiệu ứng mix sản phẩm −0,4 điểm. Bridge phải khép kín. Can thiệp trước vào mix kênh, không phải vào giá vốn.', '{}', 'Bridge lệch quá 0,3 điểm so với tổng: trần mức 2 · Tách được mix kênh thành một cấu phần riêng: mức 4 · Kết luận can thiệp vào giá vốn: sai trọng tâm, trần mức 2 ở tiêu chí kết luận.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-032', '032', 'Ứng dụng giao đồ ăn lỗ 12.000đ mỗi đơn', 'Công nghệ', 'Một ứng dụng giao đồ ăn đang xử lý 40.000 đơn mỗi ngày và lỗ khoảng 12.000 đồng trên mỗi đơn. Nhà đầu tư yêu cầu đạt hoà vốn trên mỗi đơn trong 12 tháng.', 'Dựng unit economics một đơn hàng và chỉ ra hai đòn bẩy có thể đưa về hoà vốn, kèm mức cần thay đổi.', 45, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r1', 'C-032', 'Phát sẵn', 'Giá trị đơn trung bình 120.000đ', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r2', 'C-032', 'Phát sẵn', 'Hoa hồng nhà hàng 20%', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r3', 'C-032', 'Phát sẵn', 'Phí giao thu của khách 15.000đ', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r4', 'C-032', 'Phát sẵn', 'Trả tài xế 28.000đ/đơn', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r5', 'C-032', 'Phát sẵn', 'Khuyến mãi trung bình 12.000đ/đơn', 5);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r6', 'C-032', 'Phát sẵn', 'Chi phí xử lý thanh toán 1.500đ', 6);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-032.r7', 'C-032', 'Phát sẵn', 'Chi phí chăm sóc khách hàng 1.500đ.', 7);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-032.t1', 'C-032', 'Khuyến mãi 12.000đ trông như đòn bẩy dễ nhất, nhưng cắt khuyến mãi làm giảm số đơn — và chi phí tài xế mỗi đơn sẽ tăng vì mật độ đơn thưa hơn. Nhắm FIN-06 và tư duy một chiều.', 'FIN-06');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-032', 'Doanh thu mỗi đơn: 24.000 + 15.000 = 39.000đ · Chi phí: 28.000 + 12.000 + 1.500 + 1.500 = 43.000đ · Lỗ 4.000đ trước chi phí cố định phân bổ, lỗ 12.000đ sau. Hai đòn bẩy đáng bàn: tăng giá trị đơn trung bình qua gợi ý món (mỗi 10% tăng thêm ~2.400đ doanh thu) và giảm chi phí tài xế qua ghép đơn (ghép 2 đơn giảm ~30% chi phí giao). Phải nêu ràng buộc: ghép đơn làm tăng thời gian giao.', '{}', 'Tách đúng biên đóng góp và lợi nhuận sau phân bổ: mức 4 · Chỉ đề xuất cắt khuyến mãi mà không xét tác động lên số đơn: trần mức 2 · Ước lượng được mức thay đổi cần thiết: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-037', '037', 'Chuỗi F&B 40 điểm bán, biên giảm 4 điểm', 'F&B', 'Chuỗi trà sữa 40 cửa hàng, doanh thu tăng 9% năm ngoái nhưng biên lợi nhuận hoạt động giảm từ 14% xuống 10%. Ban điều hành muốn biết chuyện gì đang xảy ra.', 'Vì sao biên lợi nhuận giảm, và làm gì để lấy lại ít nhất 2 điểm trong 12 tháng?', 60, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-037.r1', 'C-037', 'Phát sẵn', 'Exhibit 1 — P&L hai năm theo nhóm chi phí', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-037.r2', 'C-037', 'Phát sẵn', 'Exhibit 2 — doanh thu và lợi nhuận theo 40 cửa hàng, chia theo năm mở', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-037.r3', 'C-037', 'Phát sẵn', 'Exhibit 3 — giá nguyên liệu chính theo quý', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-037.r4', 'C-037', 'Phát sẵn', 'Exhibit 4 — số lượng khuyến mãi theo tháng.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-037.t1', 'C-037', 'Doanh thu tăng 9% chủ yếu đến từ 8 cửa hàng mới mở, vốn chưa đạt điểm hoà vốn. Biên của các cửa hàng cũ thực ra ổn định. Vấn đề không phải chi phí mà là tốc độ mở rộng vượt khả năng hấp thụ. Nhắm PRF-02 bỏ qua mix.', 'PRF-02');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-037', 'Tách 40 cửa hàng theo năm mở → 32 cửa hàng cũ biên ~14,5%, 8 cửa hàng mới biên −6% · Bridge biên: hiệu ứng cửa hàng mới −3,2 điểm, giá nguyên liệu −1,1 điểm, khuyến mãi −0,6 điểm, cải thiện năng suất +0,9 điểm · Khuyến nghị: hoãn mở mới hai quý, đặt điều kiện hoà vốn trước khi mở tiếp, xử lý riêng 3 cửa hàng mới yếu nhất.', '{}', 'Tách cửa hàng theo năm mở: mức 4 ở structure · Kết luận “chi phí nguyên liệu tăng”: trần mức 2 · Khuyến nghị có điều kiện mở tiếp: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-038', '038', 'Nhà sản xuất bao bì mất khách hàng lớn nhất', 'Sản xuất', 'Một nhà sản xuất bao bì giấy vừa mất hợp đồng với khách hàng chiếm 34% doanh thu. Hợp đồng kết thúc sau 4 tháng nữa.', 'Doanh nghiệp nên làm gì trong 12 tháng tới?', 60, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-038.r1', 'C-038', 'Phát sẵn', 'Exhibit 1 — cơ cấu doanh thu theo 20 khách hàng lớn nhất', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-038.r2', 'C-038', 'Phát sẵn', 'Exhibit 2 — công suất nhà máy và tỷ lệ sử dụng', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-038.r3', 'C-038', 'Phát sẵn', 'Exhibit 3 — cấu trúc chi phí cố định và biến đổi', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-038.r4', 'C-038', 'Nếu hỏi lý do mất khách', 'khách chuyển sang nhà cung cấp có nhà máy gần hơn, rẻ hơn 8%.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-038.t1', 'C-038', 'Tỷ lệ chi phí cố định cao khiến việc mất 34% doanh thu đẩy doanh nghiệp xuống dưới điểm hoà vốn, chứ không chỉ giảm lợi nhuận 34%. Người học không tính lại điểm hoà vốn sẽ đề xuất giải pháp quá nhẹ. Nhắm PRF-04.', 'PRF-04');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-038', 'Tính lại điểm hoà vốn sau khi mất khách → thiếu ~18% sản lượng · Ba hướng song song: lấp công suất (khách mới, gia công cho đối thủ), cắt chi phí cố định (một ca sản xuất, thuê ngoài khâu cắt), và giữ khách còn lại (rủi ro tập trung: 3 khách tiếp theo chiếm 29%) · Khuyến nghị phải có thứ tự và mốc thời gian trong 4 tháng còn hợp đồng.', '{}', 'Tính lại điểm hoà vốn: mức 4 · Chỉ đề xuất “tìm khách mới”: trần mức 2 · Nêu rủi ro tập trung với 3 khách còn lại: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-039', '039', 'Checkpoint profitability — ba đề tương đương', 'Bán lẻ', 'Ba đề cùng độ khó, cùng cấu trúc chấm, để luân phiên khi người học thi lại. Đề A: chuỗi phòng khám nha khoa 15 cơ sở, lợi nhuận giảm dù số bệnh nhân tăng. Đề B: doanh nghiệp may gia công mất biên khi chuyển từ đơn lớn sang đơn nhỏ. Đề C: chuỗi siêu thị mini có 3 khu vực, một khu vực kéo tụt toàn hệ thống.', 'Cùng khuôn: nguyên nhân gốc là gì và làm gì để phục hồi biên lợi nhuận?', 70, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-039.r1', 'C-039', 'Phát sẵn', 'Mỗi đề có đúng 4 exhibit: P&L hai kỳ', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-039.r2', 'C-039', 'Phát sẵn', 'phân rã theo đơn vị kinh doanh', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-039.r3', 'C-039', 'Phát sẵn', 'một chỉ số vận hành đặc thù ngành', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-039.r4', 'C-039', 'Phát sẵn', 'một exhibit gây nhiễu không dẫn tới kết luận.', 4);
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-039', 'Mỗi đề có một file khung riêng: cây kỳ vọng, bridge với các cấu phần và con số, nguyên nhân gốc, và hai khuyến nghị kèm ước lượng tác động. Ba đề phải cho ra độ khó chấm tương đương, kiểm chứng bằng phân bố điểm sau 20 lượt thi đầu.', '{}', 'Bỏ qua exhibit gây nhiễu và nói được vì sao bỏ: +1 mức ở structure · Không kịp đưa khuyến nghị: trần mức 2 toàn bài.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-042', '042', 'Chuỗi cà phê Việt mở rộng sang Philippines', 'F&B', 'Một chuỗi cà phê Việt Nam có 180 cửa hàng trong nước, biên lợi nhuận hoạt động 12%, đang cân nhắc mở rộng sang Philippines với mục tiêu 50 cửa hàng trong 5 năm.', 'Có nên vào thị trường này không? Nếu có thì vào bằng cách nào và với điều kiện gì?', 75, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-042.r1', 'C-042', 'Phát sẵn', 'Exhibit 1 — quy mô và tăng trưởng thị trường cà phê chuỗi tại 4 nước ASEAN', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-042.r2', 'C-042', 'Phát sẵn', 'Exhibit 2 — thị phần 5 chuỗi lớn nhất tại Philippines', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-042.r3', 'C-042', 'Phát sẵn', 'Exhibit 3 — kinh tế một cửa hàng tại Việt Nam', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-042.r4', 'C-042', 'Phát sẵn', 'Exhibit 4 — chi phí mặt bằng và nhân công so sánh hai nước', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-042.r5', 'C-042', 'Nếu hỏi khẩu vị', 'người tiêu dùng Philippines ưa cà phê ngọt, pha sẵn.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-042.t1', 'C-042', 'Chi phí mặt bằng tại Manila cao hơn ~60% và chi phí nhân công cao hơn ~40%, nhưng giá bán chỉ chịu được mức cao hơn ~20%. Kinh tế một cửa hàng chuyển từ 12% xuống âm nếu bê nguyên mô hình. Nhắm ENT-03 và ENT-02.', 'ENT-03');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-042', 'Sizing SAM: dân số đô thị Philippines × tỷ lệ uống cà phê chuỗi × tần suất × giá · Dựng lại kinh tế một cửa hàng với chi phí địa phương → cần doanh thu cao hơn ~35% hoặc mô hình cửa hàng nhỏ hơn · Khuyến nghị khung: vào bằng nhượng quyền tổng với đối tác địa phương thay vì tự vận hành, thử 5 cửa hàng trong 18 tháng, điều kiện tiếp tục là biên cửa hàng ≥8% sau tháng thứ 12.', '{}', 'Dựng lại kinh tế cửa hàng theo chi phí địa phương: mức 4 · Giả định chiếm x% thị phần mà không có cơ sở: trần mức 2 · Có điều kiện tiếp tục hoặc rút: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-046', '046', 'Chuỗi phòng gym thiết kế lại gói thành viên', 'Dịch vụ', 'Chuỗi phòng gym 12 cơ sở, 24.000 hội viên, đang bán ba gói: tháng, 6 tháng và năm. Tỷ lệ gia hạn thấp và doanh thu trên mỗi hội viên đi ngang hai năm.', 'Thiết kế lại cấu trúc gói để tăng doanh thu trên mỗi hội viên ít nhất 15% mà không làm giảm số hội viên quá 5%.', 70, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-046.r1', 'C-046', 'Phát sẵn', 'Dataset 24.000 hội viên: gói, giá thực trả, số lần đến mỗi tháng, thời gian gắn bó', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-046.r2', 'C-046', 'Phát sẵn', 'Exhibit 1 — phân bố tần suất đến', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-046.r3', 'C-046', 'Phát sẵn', 'Exhibit 2 — tỷ lệ gia hạn theo gói', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-046.r4', 'C-046', 'Phát sẵn', 'Exhibit 3 — chi phí phục vụ theo mức sử dụng', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-046.r5', 'C-046', 'Nếu hỏi công suất', 'giờ cao điểm đã đầy 85%.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-046.t1', 'C-046', 'Nhóm đến nhiều nhất lại là nhóm sinh lời ít nhất do chi phí phục vụ và do họ chiếm giờ cao điểm. Tăng giá đều tay sẽ đuổi mất nhóm đến ít — vốn là nhóm sinh lời nhất. Nhắm PRC-04.', 'PRC-04');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-046', 'Phân nhóm hội viên theo tần suất × thời gian gắn bó → 4 nhóm có biên đóng góp khác nhau · Đề xuất gói theo khung giờ (ngoài cao điểm rẻ hơn), gói theo số lần, và gói năm trả trước có ưu đãi · Mô hình tác động: doanh thu trên hội viên +17%, số hội viên −3%, đồng thời giảm tải giờ cao điểm · Phải nêu rủi ro hội viên cũ phản ứng khi đổi cấu trúc.', '{}', 'Nhận ra nghịch lý nhóm đến nhiều: mức 4 · Đề xuất tăng giá đồng loạt: trần mức 2 · Dùng được ràng buộc công suất giờ cao điểm: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-050', '050', 'Investment memo — chuỗi bán lẻ mua lại đối thủ khu vực', 'Bán lẻ', 'Một chuỗi siêu thị mini 210 cửa hàng ở miền Nam cân nhắc mua lại một chuỗi 60 cửa hàng ở miền Trung. Bên bán đưa giá tương đương 9 lần lợi nhuận trước lãi vay, thuế và khấu hao.', 'Có nên mua không, và ở mức giá nào? Nộp memo 2 trang.', 360, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-050.r1', 'C-050', 'Phát sẵn', 'Báo cáo tài chính 3 năm của bên mua và bên bán', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-050.r2', 'C-050', 'Phát sẵn', 'Exhibit 1 — bản đồ phủ cửa hàng hai chuỗi', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-050.r3', 'C-050', 'Phát sẵn', 'Exhibit 2 — biên lợi nhuận theo quy mô cửa hàng', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-050.r4', 'C-050', 'Phát sẵn', 'Exhibit 3 — bội số giao dịch của 5 thương vụ so sánh trong ngành', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-050.r5', 'C-050', 'Nếu hỏi hợp đồng thuê', '40% cửa hàng bên bán có hợp đồng hết hạn trong 2 năm.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-050.t1', 'C-050', 'Synergy chi phí mua hàng nghe hấp dẫn nhưng bên bán đã mua qua cùng nhà phân phối, nên phần chồng lấn nhỏ. Synergy thật nằm ở chi phí quản lý vùng và logistics. Bẫy thứ hai là 40% hợp đồng thuê sắp hết hạn — một khoản chi phí ẩn lớn. Nhắm MNA-01 và MNA-02.', 'MNA-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-050', 'Định giá độc lập bằng dòng tiền → khoảng 6,5–7,5 lần · Synergy đáng tin: quản lý vùng và logistics, tương đương ~0,8–1,2 lần bội số · Chi phí tích hợp và rủi ro thuê trừ đi ~0,5 lần · Giá trần hợp lý ~8 lần, thấp hơn giá chào · Khuyến nghị: đàm phán xuống hoặc bỏ, kèm điều kiện gia hạn hợp đồng thuê trước khi chốt.', '{}', 'Có giá trần bằng số: bắt buộc để đạt · Không nhắc hợp đồng thuê: trần mức 2 ở tiêu chí rủi ro · Phân biệt synergy đáng tin và không đáng tin: mức 4.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-054', '054', 'Thương hiệu sữa hạt chọn phân khúc ưu tiên', 'FMCG', 'Một thương hiệu sữa hạt nội địa mới có ngân sách hạn chế, đang bán dàn trải cho mọi nhóm khách và không nhóm nào nhớ tới thương hiệu.', 'Chọn một phân khúc ưu tiên cho 12 tháng tới và viết value proposition cho phân khúc đó.', 40, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-054.r1', 'C-054', 'Phát sẵn', 'Dataset khảo sát mô phỏng 1.200 người: tuổi, thu nhập, lý do dùng, tần suất, thương hiệu đang dùng', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-054.r2', 'C-054', 'Phát sẵn', 'Exhibit 1 — quy mô và tăng trưởng 5 nhóm nhu cầu', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-054.r3', 'C-054', 'Phát sẵn', 'Exhibit 2 — mức độ trung thành với thương hiệu hiện tại theo nhóm', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-054.r4', 'C-054', 'Phát sẵn', 'Exhibit 3 — sẵn sàng chi trả theo nhóm.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-054.t1', 'C-054', 'Nhóm lớn nhất (người ăn kiêng) cũng là nhóm trung thành nhất với thương hiệu quốc tế đang dẫn đầu — chi phí giành khách rất cao. Nhóm nhỏ hơn (người không dung nạp lactose) nhỏ nhưng chưa ai phục vụ riêng. Nhắm MKT-02 chọn tất cả các phân khúc.', 'MKT-02');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-054', 'Bảng chấm điểm 5 nhóm trên 4 tiêu chí: quy mô, tăng trưởng, khả năng thắng, sẵn sàng chi trả · Nhóm được chọn phải là nhóm ta có khả năng thắng, không phải nhóm to nhất · Value proposition phải có một điểm khác biệt chứng minh được, không phải “tự nhiên và tốt cho sức khoẻ”.', '{}', 'Chọn nhóm to nhất mà không xét khả năng thắng: trần mức 2 · Value proposition có điểm chứng minh được: mức 4 · Nêu rõ nhóm nào bỏ qua và vì sao: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-057', '057', 'Sàn thương mại điện tử có CAC tăng 60%', 'Công nghệ', 'Một sàn thương mại điện tử ngành hàng mẹ và bé. Trong 12 tháng, chi phí thu hút một khách hàng mới tăng từ 180.000đ lên 290.000đ, trong khi số khách mới mỗi tháng chỉ tăng 8%.', 'Điều gì đang xảy ra, và nên phân bổ lại ngân sách marketing thế nào?', 70, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-057.r1', 'C-057', 'Phát sẵn', 'Exhibit 1 — chi tiêu và khách mới theo 5 kênh, 12 tháng', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-057.r2', 'C-057', 'Phát sẵn', 'Exhibit 2 — funnel từ truy cập đến đơn đầu tiên', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-057.r3', 'C-057', 'Phát sẵn', 'Exhibit 3 — cohort giữ chân theo tháng đăng ký', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-057.r4', 'C-057', 'Phát sẵn', 'Exhibit 4 — giá trị đơn và tần suất mua theo kênh', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-057.r5', 'C-057', 'Phát sẵn', 'Exhibit 5 — biên đóng góp theo ngành hàng.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-057.t1', 'C-057', 'Kênh có CAC thấp nhất lại mang về khách có tỷ lệ quay lại thấp nhất. Tính theo LTV thì kênh đắt nhất mới là kênh sinh lời nhất. Bẫy thứ hai: CAC trung bình tăng phần lớn do một kênh đã chạm điểm bão hoà — tăng chi thêm không ra thêm khách. Nhắm MKT-05 và MKT-06.', 'MKT-05');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-057', 'Tính LTV theo biên đóng góp cho từng kênh, không theo doanh thu · Vẽ đường hiệu suất giảm dần của kênh bão hoà → điểm nên dừng tăng chi · Phân bổ lại: giảm 30% ở kênh bão hoà, chuyển sang kênh có LTV/CAC cao nhất và sang giữ chân · Ước lượng tác động: CAC trung bình giảm về ~230.000đ, số khách mới giữ nguyên, lợi nhuận đóng góp tăng.', '{}', 'Dùng biên đóng góp để tính LTV: bắt buộc để đạt · Đề xuất dồn tiền vào kênh CAC thấp nhất: trần mức 2 · Nhận ra điểm bão hoà kênh: mức 4.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-060', '060', 'Ra mắt dòng chăm sóc da nam giới', 'FMCG', 'Một công ty mỹ phẩm nội địa đang mạnh ở dòng nữ, muốn ra mắt dòng chăm sóc da nam giới với ngân sách 25 tỷ đồng cho năm đầu.', 'Xây kế hoạch ra mắt 12 tháng: phân khúc, định vị, kênh, ngân sách, chỉ số theo dõi. Nộp deck 10 slide.', 360, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-060.r1', 'C-060', 'Phát sẵn', 'Exhibit 1 — quy mô thị trường chăm sóc da nam và tăng trưởng', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-060.r2', 'C-060', 'Phát sẵn', 'Exhibit 2 — thị phần 6 thương hiệu dẫn đầu', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-060.r3', 'C-060', 'Phát sẵn', 'Exhibit 3 — hành vi mua theo nhóm tuổi', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-060.r4', 'C-060', 'Phát sẵn', 'Exhibit 4 — cơ cấu kênh phân phối ngành mỹ phẩm', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-060.r5', 'C-060', 'Phát sẵn', 'Exhibit 5 — chi phí trưng bày và chiết khấu theo kênh.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-060.t1', 'C-060', 'Ngân sách 25 tỷ nghe lớn nhưng không đủ để vừa xây thương hiệu vừa phủ kênh hiện đại toàn quốc. Kế hoạch không nêu rõ cái không làm sẽ không khả thi. Nhắm MKT-10 làm tất cả kênh cùng lúc.', 'MKT-10');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-060', 'Sizing SAM và mục tiêu doanh thu năm đầu có cơ sở · Chọn một phân khúc và một kênh chủ lực · Funnel math từ ngân sách ra số khách mua ước tính · Bảng phân bổ ngân sách có tỷ lệ xây thương hiệu / kích hoạt bán hàng và danh sách ba việc không làm · Bảng chỉ số dẫn dắt và chỉ số kết quả theo quý.', '{}', 'Không có danh sách “không làm”: trần mức 2 toàn bài · Funnel math nối ngân sách với doanh thu: mức 4 · Chỉ số là lượt xem thay vì doanh thu: trừ một mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-063', '063', 'Bếp trung tâm quá tải khung giờ trưa', 'F&B', 'Một chuỗi cơm văn phòng dùng một bếp trung tâm cung cấp cho 18 điểm giao. Từ 11h đến 13h, đơn bị trễ trung bình 22 phút và tỷ lệ huỷ đơn tăng.', 'Nút thắt nằm ở đâu, và nếu gỡ thì phục vụ thêm được bao nhiêu suất mỗi ngày?', 40, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-063.r1', 'C-063', 'Phát sẵn', 'Sơ đồ dây chuyền 6 bước với thời gian chu kỳ mỗi bước và số nhân sự', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-063.r2', 'C-063', 'Phát sẵn', 'Exhibit 1 — số đơn theo khung 15 phút', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-063.r3', 'C-063', 'Phát sẵn', 'Exhibit 2 — thời gian chờ tại từng bước', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-063.r4', 'C-063', 'Nếu hỏi thiết bị', '2 lò hấp, mỗi lò 40 suất mỗi mẻ, mỗi mẻ 18 phút.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-063.t1', 'C-063', 'Bước có hàng chờ dài nhất là đóng gói, nhưng nút thắt thật là lò hấp — hàng chờ dồn về sau nó. Gỡ khâu đóng gói không tăng được sản lượng. Nhắm OPS-01.', 'OPS-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-063', 'Công suất lò: 2 lò × 40 suất ÷ 18 phút ≈ 267 suất/giờ · Nhu cầu giờ cao điểm ~380 suất/giờ → thiếu ~30% · Thêm một lò đưa công suất lên ~400 suất/giờ, khi đó nút thắt chuyển sang đóng gói ở ~420 suất/giờ · Phương án không cần đầu tư: nấu trước một phần món giữ nhiệt, dời 15% đơn sang khung 10h45.', '{}', 'Chỉ đúng lò hấp và kiểm tra nút tiếp theo sau khi gỡ: mức 4 · Chỉ đúng khâu đóng gói: trần mức 2 · Có phương án không cần đầu tư: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-066', '066', 'Nhà phân phối dược tái thiết kế mạng lưới 5 kho', 'Y tế', 'Một nhà phân phối dược phẩm phục vụ 3.400 nhà thuốc qua 5 kho vùng. Chi phí logistics chiếm 7,2% doanh thu, cao hơn mức tham chiếu ngành. Cam kết giao trong 24 giờ cho 95% đơn.', 'Nên bố trí lại mạng lưới thế nào để giảm chi phí mà vẫn giữ cam kết dịch vụ?', 75, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-066.r1', 'C-066', 'Phát sẵn', 'Dataset: nhu cầu theo 63 tỉnh, chi phí cố định từng kho, chi phí vận chuyển theo cự ly, tồn kho bình quân từng kho', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-066.r2', 'C-066', 'Phát sẵn', 'Exhibit 1 — bản đồ nhu cầu', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-066.r3', 'C-066', 'Phát sẵn', 'Exhibit 2 — cơ cấu chi phí logistics', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-066.r4', 'C-066', 'Phát sẵn', 'Exhibit 3 — tỷ lệ giao đúng hạn theo kho', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-066.r5', 'C-066', 'Nếu hỏi hàng lạnh', '18% mã hàng cần bảo quản lạnh.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-066.t1', 'C-066', 'Gộp kho giảm chi phí cố định và giảm tồn kho nhờ gộp rủi ro, nhưng làm tăng cự ly giao và phá cam kết 24 giờ ở vùng xa. Bẫy thứ hai: 18% hàng lạnh không thể gộp tuỳ tiện. Nhắm SCM-01 và SCM-02.', 'SCM-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-066', 'Ba phương án: giữ 5 kho tối ưu tuyến · gộp còn 3 kho lớn · mô hình 2 kho lớn cộng 3 điểm trung chuyển nhỏ · Bảng trade-off cho từng phương án: chi phí cố định, chi phí vận chuyển, tồn kho, tỷ lệ giao đúng hạn · Phương án 3 thường thắng: giữ được cam kết dịch vụ, giảm tồn kho nhờ gộp, chi phí cố định trung gian.', '{}', 'Có định lượng tác động lên tỷ lệ giao đúng hạn: bắt buộc để đạt · Bỏ qua hàng lạnh: trần mức 2 ở rủi ro · Tính được lợi ích gộp rủi ro lên tồn kho: mức 4.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-068', '068', '200 khách B2B, 30% đang lỗ', 'Bán lẻ', 'Một nhà sản xuất hàng tiêu dùng bán cho 200 khách B2B: chuỗi siêu thị, nhà phân phối, cửa hàng lớn. Kế toán quản trị vừa báo 30% số khách có lợi nhuận âm sau khi phân bổ chi phí phục vụ.', 'Nên làm gì với nhóm khách đang lỗ?', 80, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-068.r1', 'C-068', 'Phát sẵn', 'Dataset 200 khách: doanh thu, biên gộp, số đơn, quy mô đơn trung bình, số lần giao, chiết khấu, chi phí hỗ trợ trưng bày, số lần trả hàng', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-068.r2', 'C-068', 'Phát sẵn', 'Exhibit 1 — phân bố lợi nhuận theo khách', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-068.r3', 'C-068', 'Phát sẵn', 'Exhibit 2 — chi phí phục vụ theo quy mô đơn', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-068.r4', 'C-068', 'Nếu hỏi chi phí cố định', '35% chi phí phục vụ là cố định ở cấp hệ thống.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-068.t1', 'C-068', 'Ngừng phục vụ nhóm lỗ không làm chi phí cố định biến mất — nó chỉ dồn sang các khách còn lại. Bẫy thứ hai: một số khách lỗ là khách lớn có tác dụng lấp công suất và có sức mặc cả. Nhắm SCM-06.', 'SCM-06');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-068', 'Phân 200 khách thành bốn nhóm theo biên đóng góp và quy mô · Nhóm A biên dương cao: giữ và mở rộng · Nhóm B biên dương thấp, chi phí phục vụ cao: tái đàm phán quy mô đơn tối thiểu và tần suất giao · Nhóm C biên âm nhưng lấp công suất: giữ có điều kiện · Nhóm D biên âm và nhỏ: ngừng hoặc chuyển sang nhà phân phối · Ước lượng tác động: cải thiện lợi nhuận mà chỉ mất ~4% doanh thu.', '{}', 'Đề xuất bỏ hết nhóm lỗ: trần mức 2 · Phân biệt chi phí cố định và biến đổi trong chi phí phục vụ: mức 4 · Có phương án tái đàm phán thay vì chỉ giữ hoặc bỏ: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-072', '072', 'Checkpoint đọc dọc — 12 action title', 'Đa ngành', 'Hai bộ tài liệu thô, mỗi bộ khoảng 15 trang gồm bảng số, ghi chú phỏng vấn và exhibit rời, chưa có kết luận nào.', 'Viết một trang pyramid và 12 action title sao cho người chấm chỉ đọc tiêu đề là hiểu trọn lập luận và biết khuyến nghị là gì.', 50, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-072.r1', 'C-072', 'Phát sẵn', 'Bộ A — chuỗi rửa xe muốn tăng doanh thu. Bộ B — công ty phần mềm kế toán mất khách hàng nhỏ. Mỗi bộ có ít nhất hai dữ kiện mâu thuẫn nhau để buộc người học chọn phía.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-072.t1', 'C-072', 'Tài liệu thô chứa nhiều thông tin thú vị nhưng không dẫn tới khuyến nghị. Người học ôm hết sẽ có 12 tiêu đề rời rạc. Nhắm STO-01 và SYN-02.', 'STO-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-072', 'Mỗi bộ có một governing thought mẫu và ba nhánh mẫu, kèm danh sách các dữ kiện nên bị cắt và lý do. Bản chấm đối chiếu theo cấu trúc, không theo câu chữ.', '{}', 'Người chấm đọc 12 tiêu đề, không xem gì khác, và phải nói lại được khuyến nghị. Không nói được: trần mức 2 bất kể nội dung bên dưới.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-078', '078', 'Checkpoint storyboard, deck và bản ghi', 'Đa ngành', 'Một case đã được giải sẵn, có đầy đủ phân tích và số liệu. Người học không phải phân tích lại — nhiệm vụ chỉ là trình bày.', 'Nộp ba thứ: storyboard 12 khung trên giấy, deck 12 slide, và bản ghi 7 phút.', 360, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-078.r1', 'C-078', 'Phát sẵn', 'Bộ phân tích hoàn chỉnh của case C-037 hoặc C-057', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-078.r2', 'C-078', 'Phát sẵn', 'Hai đối tượng nghe được chỉ định ngẫu nhiên: ban giám khảo cuộc thi, hoặc ban điều hành doanh nghiệp.', 2);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-078.t1', 'C-078', 'Đối tượng nghe khác nhau đòi cấu trúc khác nhau: giám khảo cần thấy độ chặt của phân tích, ban điều hành cần thấy quyết định và nguồn lực. Người học dùng chung một deck cho cả hai sẽ mất điểm. Nhắm STO-05.', 'STO-05');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-078', 'Hai storyline mẫu cho hai đối tượng, cùng dữ liệu nhưng khác thứ tự và khác độ sâu ở phần phương pháp. Bản ghi mẫu ở hai mức điểm để đối chiếu.', '{}', 'Storyboard làm sau deck (nhận ra qua thứ tự nộp hoặc qua độ khớp quá hoàn hảo): trừ một mức · Vượt 7 phút quá 40%: trần mức 2 ở nhịp trình bày.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-081', '081', 'Vòng thi 24 giờ theo team', 'Đa ngành', 'Một đề thi mở do doanh nghiệp đối tác đặt hàng, phát cho nhóm 4 người. Mô phỏng đúng thể thức một vòng loại: đề mơ hồ, dữ liệu không đầy đủ, hạn nộp cứng.', 'Tuỳ đề. Yêu cầu nộp: ghost deck ở giờ thứ 3, deck hoàn chỉnh đúng hạn, và nhật ký quy trình.', 1440, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-081.r1', 'C-081', 'Phát sẵn', 'Bộ tài liệu nền 20–30 trang: báo cáo ngành, số liệu công ty, ghi chú phỏng vấn nội bộ', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-081.r2', 'C-081', 'Phát sẵn', 'Một hộp thư hỏi đáp: team được gửi tối đa 5 câu hỏi trong 24 giờ và nhận trả lời sau 2 giờ.', 2);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-081.t1', 'C-081', 'Bộ tài liệu chứa khoảng 40% thông tin không dẫn tới kết luận. Giới hạn 5 câu hỏi buộc team phải chọn hỏi cái gì. Nhắm CMP-01 phân tích quá lâu rồi làm slide vội.', 'CMP-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-081', 'Không có đáp án đúng. Thay vào đó có bộ tiêu chí chấm quy trình: ghost deck nộp đúng giờ thứ 3, có ít nhất ba mốc hợp nhất ghi trong nhật ký, và phạm vi được cắt ít nhất một lần có ghi lý do. Deck chấm bằng R3.', '{}', 'Không có ghost deck giờ thứ 3: trần mức 2 ở tiêu chí quy trình · Nộp trễ: không chấm, làm lại vòng khác · Năm câu hỏi đều về dữ liệu team tự ước lượng được: trừ một mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-088', '088', 'Checkpoint pitch 7 phút và Q&A 10 phút', 'Đa ngành', 'Panel ba người đóng vai ban giám khảo: một người hỏi về con số, một người hỏi về tính khả thi, một người hỏi phản biện chiến lược.', 'Team trình bày deck của C-081 trong 7 phút, sau đó chịu 10 phút hỏi đáp.', 20, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-088.r1', 'C-088', 'Phát sẵn', 'Ngân hàng 12 câu hỏi phân loại: 4 câu về con số (“con số 18% ở slide 6 từ đâu ra”), 4 câu về khả thi (“ai trong tổ chức sẽ làm việc này”), 4 câu phản biện (“nếu đối thủ hạ giá ngay tháng sau thì sao”). Panel chọn 8 câu, bắt buộc đủ ba loại.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-088.t1', 'C-088', 'Một câu hỏi cố ý dựa trên một con số trong appendix chứ không phải trong deck chính — kiểm tra xem team có thật sự làm phần phụ lục hay không. Nhắm PIT-05.', 'PIT-05');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-088', 'Với mỗi câu hỏi có một khung trả lời tốt: câu đầu là câu trả lời, hai câu sau là lý do, rồi dừng. Bản ghi mẫu ba mức để người chấm hiệu chuẩn.', '{}', 'Không ai trong team trả lời được câu về con số: trần mức 2 toàn bài · Trả lời vòng vo quá 60 giây cho một câu: trừ một mức ở tiêu chí trả lời trực diện · Thừa nhận giới hạn rồi nêu cách kiểm chứng: mức 4.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-090', '090', 'FMCG — độ phủ, chiết khấu và kinh tế nhà phân phối', 'FMCG', 'Một thương hiệu nước giặt nội địa có độ phủ 42% cửa hàng tạp hoá ở miền Bắc nhưng chỉ 18% ở miền Nam, dù chi cho kênh phân phối như nhau.', 'Vì sao chênh lệch, và nên làm gì?', 25, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-090.r1', 'C-090', 'Phát sẵn', 'Exhibit 1 — độ phủ và doanh số theo vùng', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-090.r2', 'C-090', 'Phát sẵn', 'Exhibit 2 — cơ cấu chiết khấu cho nhà phân phối và cho cửa hàng', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-090.r3', 'C-090', 'Nếu hỏi số nhà phân phối', 'miền Bắc 34, miền Nam 11', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-090.r4', 'C-090', 'Nếu hỏi biên của nhà phân phối', 'miền Nam thấp hơn 2 điểm do cự ly giao xa hơn.', 4);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-090.t1', 'C-090', 'Vấn đề không nằm ở người tiêu dùng mà ở kinh tế của nhà phân phối: biên quá mỏng nên họ không đẩy hàng. Người học quen tư duy thương hiệu sẽ đề xuất tăng quảng cáo. Nhắm IND-03.', 'IND-03');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-090', 'Tính lợi nhuận một nhà phân phối miền Nam → thấp hơn ngưỡng họ chấp nhận · Ba đòn bẩy: tăng chiết khấu có điều kiện theo độ phủ, chia nhỏ địa bàn để giảm cự ly giao, hoặc chuyển một phần sang mô hình giao trực tiếp cho cửa hàng lớn · Chọn theo chi phí trên một điểm phủ tăng thêm.', '{}', 'Tính được kinh tế của nhà phân phối: mức 4 · Đề xuất tăng quảng cáo: trần mức 2 · Nêu chi phí trên một điểm phủ tăng thêm: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-092', '092', 'Ngân hàng số giành khách hàng trẻ', 'Bán lẻ', 'Một ngân hàng thương mại cỡ trung muốn tăng thị phần khách hàng 18–28 tuổi. Hiện nhóm này chiếm 9% số tài khoản và 2% lợi nhuận bán lẻ.', 'Có đáng theo đuổi nhóm này không, và nếu có thì theo đuổi thế nào?', 60, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-092.r1', 'C-092', 'Phát sẵn', 'Exhibit 1 — lợi nhuận trên mỗi khách theo nhóm tuổi', 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-092.r2', 'C-092', 'Phát sẵn', 'Exhibit 2 — chi phí thu hút theo kênh', 2);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-092.r3', 'C-092', 'Phát sẵn', 'Exhibit 3 — sản phẩm sử dụng theo nhóm tuổi', 3);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-092.r4', 'C-092', 'Phát sẵn', 'Exhibit 4 — đường lợi nhuận theo thời gian gắn bó', 4);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-092.r5', 'C-092', 'Phát sẵn', 'Ghi chú ràng buộc: quy định về mở tài khoản từ xa và về cho vay tín chấp với khách chưa có lịch sử tín dụng.', 5);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-092.t1', 'C-092', 'Nhóm trẻ hiện lỗ trên mỗi khách, nhưng exhibit 4 cho thấy lợi nhuận tăng mạnh sau năm thứ 4. Đây là bài toán đầu tư dài hạn, không phải bài toán lợi nhuận năm nay. Bẫy thứ hai: ràng buộc pháp lý giới hạn các sản phẩm có thể bán. Nhắm IND-04 và IND-06.', 'IND-04');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-092', 'Tính giá trị vòng đời có chiết khấu cho khách trẻ → dương nếu giữ được trên 5 năm · Điều kiện then chốt là tỷ lệ giữ chân, không phải chi phí thu hút · Khuyến nghị: theo đuổi với sản phẩm được phép (tài khoản thanh toán, tiết kiệm, thẻ ghi nợ), đặt chỉ số theo dõi là tỷ lệ giữ chân năm thứ hai, và đặt ngưỡng dừng nếu chỉ số đó dưới mức nào đó.', '{}', 'Dùng giá trị vòng đời thay vì lợi nhuận năm hiện tại: mức 4 · Không nhắc ràng buộc pháp lý: trần mức 2 · Có ngưỡng dừng: +1 mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-094', '094', 'Checkpoint Industry — chín case ngắn, rút ba', 'Đa ngành', 'Chín case ngắn thuộc chín ngành, mỗi case 25 phút. Người học rút ba, bắt buộc khác nhóm ngành.', 'Tiêu dùng: chuỗi cửa hàng thời trang giảm doanh thu trên mét vuông · nhà hàng buffet giảm vòng quay bàn · hãng nước giải khát mất kệ trưng bày. Dịch vụ & tài chính: công ty bảo hiểm có tỷ lệ bồi thường tăng · bệnh viện tư thiếu công suất giường · trung tâm tiếng Anh có tỷ lệ hoàn thành khoá thấp. Tech & hạ tầng: công ty SaaS có tỷ lệ rời bỏ tăng ở gói nhỏ · hãng giao hàng có chi phí chặng cuối tăng · nhà máy điện mặt trời có sản lượng thấp hơn dự báo.', 90, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-094.r1', 'C-094', 'Phát sẵn', 'Mỗi case có đúng 2 exhibit và một bộ chỉ số ngành. Không phát thêm.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-094.t1', 'C-094', 'Mỗi case có một chỉ số ngành mà nếu không dùng thì không thể ra kết luận đúng — ví dụ doanh thu trên mét vuông, vòng quay bàn, tỷ lệ bồi thường, công suất giường. Nhắm IND-01.', 'IND-01');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-094', 'Mỗi case có file khung: chỉ số ngành then chốt, phép tính chính, nguyên nhân gốc, một khuyến nghị. Độ khó phải tương đương giữa chín case, kiểm chứng bằng phân bố điểm.', '{}', 'Không dùng chỉ số ngành đặc thù: trần mức 2 ở tiêu chí đó, bất kể kết luận đúng hay sai.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-096', '096', 'Bộ 20 live case interviewer-led', 'Đa ngành', 'Hai mươi case ngắn viết theo khuôn interviewer-led, mỗi case có kịch bản điều phối chi tiết để người đóng vai interviewer không cần là chuyên gia.', 'Phần mở 2 phút · Yêu cầu structure 5 phút · Một câu hỏi định lượng 8 phút · Một exhibit 7 phút · Một câu hỏi phán đoán 3 phút · Chốt cuối 60 giây. Kịch bản ghi rõ interviewer nói gì ở từng mốc và can thiệp khi nào.', 30, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-096.r1', 'C-096', 'Phát sẵn', 'Mỗi case có một trang dữ liệu chỉ interviewer thấy, chia theo điều kiện: hỏi gì thì cho gì. Có ba con số mồi mà nếu người học không hỏi thì không được cho.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-096.t1', 'C-096', 'Kịch bản có một điểm interviewer ngắt lời để đổi hướng đột ngột, kiểm tra khả năng giữ mạch. Nhắm ITV-03 quên tóm tắt trước khi chuyển nhánh.', 'ITV-03');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-096', 'Mỗi case có cây kỳ vọng, đáp số của câu định lượng, thông điệp của exhibit, và hai câu chốt mẫu ở hai mức chất lượng.', '{}', 'Im lặng quá 20 giây mà không xin thời gian: trừ một mức ở giao tiếp · Hết giờ chưa kết luận: trần mức 2 ở tiêu chí kết luận · Tự tóm tắt trước mỗi lần chuyển nhánh: mức 4.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-098', '098', 'Sáu case có dữ liệu bác bỏ giả thuyết', 'Đa ngành', 'Sáu case candidate-led, mỗi case được thiết kế để giả thuyết tự nhiên nhất của người học bị dữ liệu bác bỏ ở khoảng phút thứ 15.', 'Case 1: doanh thu giảm, mọi dấu hiệu chỉ về đối thủ mới, nhưng dữ liệu cho thấy thị phần không đổi — vấn đề là cả thị trường co lại. Case 2: chi phí tăng, người học nghĩ do giá nguyên liệu, dữ liệu cho thấy giá nguyên liệu giảm — vấn đề là hao hụt.', 35, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-098.r1', 'C-098', 'Phát sẵn', 'Dữ liệu bác bỏ chỉ được phát khi người học hỏi đúng câu. Nếu sau phút 20 vẫn chưa hỏi, interviewer chủ động đưa ra để case không bế tắc, và ghi lại việc đó vào phiếu chấm.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-098.t1', 'C-098', 'Bẫy chính là tâm lý: người học đã đầu tư công sức vào một hướng sẽ cố bám. Nhắm ITV-07.', 'ITV-07');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-098', 'Mỗi case có hai cây: cây người học thường vẽ ban đầu, và cây đúng sau khi có dữ liệu mới. Phần chấm tập trung vào cách chuyển giữa hai cây, không phải vào việc có đoán đúng từ đầu hay không.', '{}', 'Thừa nhận giả thuyết cũ sai và nói rõ hướng mới: mức 4 · Tiếp tục đào hướng cũ sau khi có dữ liệu bác bỏ: trần mức 2 toàn bài · Phải được interviewer mớm mới đổi hướng: trừ một mức.');
INSERT INTO cases (id, lesson_id, title, industry, context, question, duration_min, is_fictional, status, pilot_runs, version) VALUES ('C-100', '100', 'Full loop — hai case và phần fit', 'Đa ngành', 'Mô phỏng trọn một buổi phỏng vấn: ba người phỏng vấn khác nhau, không trao đổi với nhau trước, gặp người học liên tiếp trong 2,5 giờ.', 'Vòng 1 — case interviewer-led 30 phút rút từ C-096 · Vòng 2 — case candidate-led 35 phút rút từ C-098 · Vòng 3 — fit 30 phút với 6 câu hỏi rút từ ngân hàng 20 câu · Nghỉ 10 phút giữa các vòng, đúng như thực tế.', 150, 1, 'draft', 0, 1);
INSERT INTO case_reveal_items (id, case_id, trigger, content, sort) VALUES ('C-100.r1', 'C-100', 'Phát sẵn', 'Người phỏng vấn nhận phiếu chấm riêng, không biết điểm của vòng trước. Người học không được biết kết quả cho tới khi kết thúc cả ba vòng.', 1);
INSERT INTO case_traps (id, case_id, description, mistake_code) VALUES ('C-100.t1', 'C-100', 'Vòng 2 được thiết kế khó hơn vòng 1 để kiểm tra phản ứng sau một case không suôn sẻ. Nhắm ITV-10 mất bình tĩnh sau một case tệ.', 'ITV-10');
INSERT INTO case_answer_frames (case_id, structure_md, key_numbers, quick_scoring_md) VALUES ('C-100', 'Không có. Thay vào đó là bản tổng hợp cuối buổi: ba phiếu chấm, mistake log gộp, và một kế hoạch hai tuần do chính người học viết dựa trên ba phiếu đó.', '{}', 'Điểm vòng 2 thấp hơn vòng 1 quá 15 điểm: ghi nhận vấn đề phong độ, đề xuất luyện thêm áp lực liên tiếp · Câu chuyện fit không có kết quả đo được: trần mức 2 ở phần fit · Không có câu hỏi ngược cho người phỏng vấn: trừ một mức.');
