INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-01', 'Vòng thi 48 giờ theo team', 'Trả lời một đề thi mở theo nhóm 4 người trong 48 giờ, từ đọc đề đến bảo vệ trước ban giám khảo.', 'Bán lẻ hiện đại hoặc chuỗi F&B tại Việt Nam, đề do doanh nghiệp đối tác đặt hàng.', 'Deck 15 slide + 8 slide appendix · Ghost deck nộp ở giờ thứ 6 · Pitch 7 phút · Q&A 10 phút · Nhật ký quy trình của team.', '{"R3 Slide deck": 40, "R4 Pitching": 30, "R2 Recommendation": 20, "Quy trình và mốc": 10}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-02', 'Full loop consulting interview', 'Đi trọn một vòng phỏng vấn mô phỏng trong một buổi: hai case và một phần fit, với ba người phỏng vấn khác nhau.', 'Hai ngành ngẫu nhiên rút từ thư viện H, người học không biết trước.', 'Bản ghi ba phần · Ghi chú của người phỏng vấn · Mistake log tự lập · Kế hoạch hai tuần trước ngày phỏng vấn thật.', '{"R5 Consulting interview ×2": 60, "Fit có cấu trúc và kết quả đo được": 25, "Giữ phong độ ở phần cuối": 15}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-03', 'Business expansion: vào một thị trường mới', 'Quyết định có nên đưa một mô hình đang vận hành tốt ở Việt Nam sang một thị trường Đông Nam Á khác, và vào bằng cách nào.', 'Chuỗi dịch vụ tiêu dùng (cà phê, phòng tập, giáo dục ngắn hạn).', 'Mô hình sizing hai chiều · Đánh giá cạnh tranh · Mô hình tài chính 5 năm · Khuyến nghị go/no-go kèm ngưỡng và điều kiện rút · Deck 12 slide.', '{"R1 Case answer": 30, "R6 Quantitative model": 30, "R2 Recommendation": 25, "R3 Deck": 15}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-04', 'Marketing strategy cho một thương hiệu thật', 'Giành lại hai điểm thị phần trong 12 tháng với ngân sách cho trước, không được tăng ngân sách.', 'FMCG hoặc chăm sóc cá nhân, dữ liệu thị trường công khai.', 'Sizing và phân khúc · Funnel math hiện trạng · Bảng CAC/LTV theo kênh · Kế hoạch phân bổ ngân sách kèm danh sách “không làm” · Bảng chỉ số theo dõi · Deck 12 slide.', '{"Nối với mục tiêu kinh doanh": 25, "Định lượng funnel và kênh": 30, "R2 Recommendation": 25, "R3 Deck": 20}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-05', 'Tối ưu mạng lưới chuỗi cung ứng', 'Giảm 12% tổng chi phí logistics mà không hạ mức dịch vụ dưới ngưỡng cam kết với khách hàng.', 'Phân phối dược phẩm hoặc hàng tiêu dùng nhanh, mạng lưới đa kho.', 'Mô hình chi phí mạng lưới trên bảng tính · Ba phương án cấu hình kho · Bảng trade-off cost vs service · Phân tích rủi ro vận hành và lộ trình chuyển đổi · Deck 10 slide.', '{"R6 Quantitative model": 35, "Định lượng mức dịch vụ": 25, "R2 Recommendation": 25, "Khả thi chuyển đổi": 15}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-06', 'Turnaround: doanh nghiệp đang lỗ', 'Đưa một doanh nghiệp từ lỗ về hoà vốn trong 18 tháng, với thứ tự can thiệp rõ ràng cho 90 ngày đầu.', 'Sản xuất công nghiệp nhẹ hoặc chuỗi bán lẻ quy mô vừa.', 'Chẩn đoán nguyên nhân gốc có bridge · Mô hình đường về hoà vốn · Kế hoạch 90 ngày với người chịu trách nhiệm · Đánh giá rủi ro nhân sự và khách hàng · Memo 3 trang.', '{"Chẩn đoán đúng nguyên nhân gốc": 30, "R6 Mô hình": 25, "Thứ tự can thiệp": 25, "Rủi ro và tính khả thi": 20}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-07', 'Decision memo cho một quyết định thật', 'Biến một câu hỏi mơ hồ ở nơi làm việc thành một quyết định có bằng chứng, đủ để một người quản lý ký duyệt.', 'Do người học chọn: công ty đang làm, hoặc một dataset mở được duyệt trước.', 'Memo 2 trang: vấn đề, phương án, tiêu chí so sánh, phân tích dữ liệu, khuyến nghị, rủi ro · Phụ lục mô hình · Bài trình bày 10 phút.', '{"R2 Recommendation": 35, "Chất lượng phân tích dữ liệu": 30, "Tiêu chí so sánh phương án": 20, "Trình bày cho người ra quyết định": 15}');
INSERT INTO capstones (id, title, objective, industry, deliverable, rubric_mix) VALUES ('CP-08', 'Kinh tế nền tảng: cân bằng hai phía của một marketplace', 'Thiết kế lại cơ chế giá và trợ giá để nền tảng đạt hoà vốn trên mỗi giao dịch mà không mất thanh khoản ở một phía.', 'Giao hàng chặng cuối, gọi xe hoặc sàn dịch vụ tại nhà.', 'Unit economics hai phía · Mô hình độ nhạy của cung và cầu theo giá · Ba phương án cơ chế giá · Phân tích phản ứng đối thủ · Deck 12 slide.', '{"R6 Mô hình hai phía": 35, "Hiểu hiệu ứng mạng": 25, "R2 Recommendation": 25, "Phản ứng đối thủ": 15}');
